{
  "content_version": "1.0.0",
  "blueprint_id": "mapping_v1-r3-hard",
  "title": "标本楼交接检查",
  "story": "生态实验楼闭馆前，你受托完成标本交接。三间相连实验室里留存采样资料和维护装置，需逐一核对材料，理清符号与设备对应关系，才能通过离楼检查。",
  "rooms": {
    "G1": {
      "name": "标本准备室",
      "description": "靠墙的标本柜半开着，操作台上散放着采样登记卡、符号对照表和旧设备清单。"
    },
    "G2": {
      "name": "材料分析室",
      "description": "中央实验台排列着培养皿，角落的电路板指示灯微亮，白板上贴着两段编码便签。"
    },
    "G3": {
      "name": "离楼检查室",
      "description": "门禁旁挂着两页设备排班表，物品交接台空着，离楼前需在此完成最后核验。"
    }
  },
  "objects": {
    "obj_key": {
      "name": "标本柜钥匙",
      "description": "一把铜色旧钥匙，可反复开启标本柜，暂存于准备室抽屉。"
    },
    "obj_code_source": {
      "name": "采样登记卡",
      "description": "卡片上按采样顺序列出四个符号，似乎可与对照表组合出编码。"
    },
    "obj_relation": {
      "name": "符号对照表",
      "description": "表中每个符号旁标有一个数字，另附设备栏供顺序谜题参考。"
    },
    "obj_device_source": {
      "name": "旧设备清单",
      "description": "清单按字母序记着几种维护设备，符号与设备需对照使用。"
    },
    "obj_puzzle_1": {
      "name": "标本柜数字锁",
      "description": "四位数字锁，需结合采样登记卡与符号对照表推得密码。"
    },
    "obj_puzzle_2": {
      "name": "设备启动顺序盘",
      "description": "面板上排列四个设备槽，需按旧设备清单与对照表安排正确顺序。"
    },
    "obj_puzzle_3": {
      "name": "分析室电路板",
      "description": "电路板指示灯闪烁，需按接线规则恢复通路才能继续后续检查。"
    },
    "obj_extra_code_a": {
      "name": "培养皿标签甲",
      "description": "第一组培养皿底贴有两位数字，为编码拼接的前半段资料。"
    },
    "obj_extra_code_b": {
      "name": "培养皿标签乙",
      "description": "另一组培养皿底另贴两位数字，与标签甲共同构成完整编码。"
    },
    "obj_puzzle_4": {
      "name": "白板编码锁",
      "description": "白板旁的四位数字锁，需将两组标签信息拼接后输入。"
    },
    "obj_extra_devices_a": {
      "name": "设备排班表上页",
      "description": "排班表上页记录两种维护设备的顺序，作为拼接资料前半段。"
    },
    "obj_extra_devices_b": {
      "name": "设备排班表下页",
      "description": "排班表下页记录另两种设备的顺序，与上页衔接成完整排班。"
    },
    "obj_puzzle_5": {
      "name": "离楼设备核对盘",
      "description": "检查室门旁的设备盘需按排班表拼接顺序摆放维护设备。"
    },
    "obj_puzzle_6": {
      "name": "标本交接箱",
      "description": "空交接箱需放入指定的标本资料袋，完成离楼最后一项。"
    }
  },
  "parameters": {
    "code_symbols": ["A", "B", "C", "D"],
    "digit_map": {
      "A": "3",
      "B": "7",
      "C": "1",
      "D": "9"
    },
    "sequence_symbols": ["E", "F", "G", "H"],
    "device_map": {
      "E": "device_b",
      "F": "device_d",
      "G": "device_a",
      "H": "device_c"
    },
    "extra_digits": ["4", "6", "8", "2"],
    "extra_devices": ["device_c", "device_a", "device_d", "device_b"]
  }
}
